// scenes/_figures.mjs — 人只给背影：远处站着的背影、后颈和肩、围巾。
//
// 没有脸、没有五官、没有手指。按 howto/角色.md 的降级条款：没有生图能力就只出手和背影。
// 轮廓靠「骨白版偏移 -3,-2 → 墨版压在上面」做出亮边，这就是套印没对准的那一线。

import { C, lerp, fillPoly } from './_print.mjs';

/** 一条由点到点、从深到浅（宽到窄）的带子。围巾、纸带都用它。 */
export function ribbon(g, pts, w0, w1, color, { taperPow = 0.85, alpha = 1 } = {}) {
  const n = pts.length;
  if (n < 2) return;
  const L = [];
  const R = [];
  for (let i = 0; i < n; i++) {
    const p = pts[i];
    const a = pts[Math.max(0, i - 1)];
    const b = pts[Math.min(n - 1, i + 1)];
    const dx = b[0] - a[0];
    const dy = b[1] - a[1];
    const d = Math.hypot(dx, dy) || 1;
    const w = lerp(w0, w1, Math.pow(i / (n - 1), taperPow)) / 2;
    L.push([p[0] - (dy / d) * w, p[1] + (dx / d) * w]);
    R.push([p[0] + (dy / d) * w, p[1] - (dx / d) * w]);
  }
  g.save();
  g.globalAlpha *= alpha;
  g.beginPath();
  L.forEach(([x, y], i) => (i ? g.lineTo(x, y) : g.moveTo(x, y)));
  for (let i = n - 1; i >= 0; i--) g.lineTo(R[i][0], R[i][1]);
  g.closePath();
  g.fillStyle = color;
  g.fill();
  g.restore();
}

/**
 * 围巾尾巴的采样点。angle 是从「正左方」往下量的弧度（0=横飞，1.1=垂下）；
 * sag 是中间下垂的量，让布不是一根直线。
 */
export function tailPts(px, py, angle, len, { n = 16, sag = 0, twist = 0 } = {}) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const p = i / n;
    const a = angle * (0.68 + 0.32 * p) + twist * Math.sin(p * Math.PI) * 0.12;
    const r = len * p;
    pts.push([px - Math.cos(a) * r, py + Math.sin(a) * r + sag * Math.sin(Math.PI * p)]);
  }
  return pts;
}

/** 远处站着的背影：h 是总高（头顶到脚底）。只给背影，没有脸。 */
export function standBack(g, { x, feetY, h, scarfAngle = 1.1, sway = 0, coat = '#201915' } = {}) {
  const headR = h * 0.053;
  const headY = feetY - h * 0.945;
  const neckY = feetY - h * 0.858;
  const shoulderY = feetY - h * 0.805;
  const hemY = feetY - h * 0.35;
  const s = sway * h * 0.012;

  // 腿和鞋：比大衣再深一档
  fillPoly(g, [
    [x - h * 0.078, hemY - h * 0.01],
    [x - h * 0.012, hemY - h * 0.01],
    [x - h * 0.022, feetY - h * 0.01],
    [x - h * 0.086, feetY - h * 0.01],
  ], '#141110', { amp: 1, seed: 33 });
  fillPoly(g, [
    [x + h * 0.012, hemY - h * 0.01],
    [x + h * 0.078, hemY - h * 0.01],
    [x + h * 0.086, feetY - h * 0.01],
    [x + h * 0.022, feetY - h * 0.01],
  ], '#141110', { amp: 1, seed: 34 });
  fillPoly(g, [[x - h * 0.09, feetY - h * 0.012], [x - h * 0.02, feetY - h * 0.012], [x - h * 0.014, feetY], [x - h * 0.1, feetY]], '#0d0b0a', { amp: 1, seed: 35 });
  fillPoly(g, [[x + h * 0.02, feetY - h * 0.012], [x + h * 0.088, feetY - h * 0.012], [x + h * 0.096, feetY], [x + h * 0.016, feetY]], '#0d0b0a', { amp: 1, seed: 36 });

  // 大衣
  const body = [
    [x - h * 0.128 - s, neckY],
    [x - h * 0.162, shoulderY + h * 0.01],
    [x - h * 0.142, hemY],
    [x + h * 0.152 + s * 1.5, hemY - h * 0.008],
    [x + h * 0.158, shoulderY + h * 0.01],
    [x + h * 0.128 + s, neckY],
  ];
  fillPoly(g, body, coat, { amp: 1.6, seed: 31 });

  // 亮边：只在大衣的左轮廓上一线（灯在左上）
  g.beginPath();
  g.moveTo(x - h * 0.128 - s, neckY);
  g.quadraticCurveTo(x - h * 0.17, shoulderY, x - h * 0.142, hemY);
  g.strokeStyle = C.boneDim;
  g.lineWidth = Math.max(1.6, h * 0.007);
  g.stroke();

  // 头、发髻
  g.beginPath();
  g.ellipse(x, headY, headR * 0.9, headR, 0, 0, Math.PI * 2);
  g.fillStyle = C.ink;
  g.fill();
  g.beginPath();
  g.arc(x + headR * 0.62, headY + headR * 0.1, headR * 0.46, 0, Math.PI * 2);
  g.fillStyle = '#0b0908';
  g.fill();
  g.beginPath();
  g.arc(x, headY, headR * 0.92, Math.PI * 1.02, Math.PI * 1.6);
  g.strokeStyle = C.boneDim;
  g.lineWidth = Math.max(1.4, h * 0.006);
  g.stroke();

  // 围巾：脖子上一条，尾端往左飘。黄版先垫一层鬼影。
  const band = [
    [x - h * 0.085, neckY + h * 0.004],
    [x - h * 0.03, neckY - h * 0.018],
    [x + h * 0.045, neckY - h * 0.019],
    [x + h * 0.088, neckY + h * 0.006],
    [x + h * 0.08, neckY + h * 0.032],
    [x - h * 0.08, neckY + h * 0.03],
  ];
  const tail = tailPts(x - h * 0.06, neckY + h * 0.022, scarfAngle, h * 0.36, { n: 16, sag: h * 0.035 });
  g.save();
  g.translate(3, -2);
  g.globalAlpha = 0.85;
  fillPoly(g, band, C.amberDim, { amp: 1.4, seed: 5 });
  ribbon(g, tail, h * 0.05, h * 0.017, C.amberDim);
  g.restore();
  fillPoly(g, band, C.bone, { amp: 1.4, seed: 5 });
  ribbon(g, tail, h * 0.047, h * 0.015, C.bone);
}

/**
 * 画面右缘的近景背影：肩、后颈、发髻、围巾。其余裁在画外。
 * 围巾从脖子（约 1720,350）飞出去，angle=0 是横飞，>0 是往下垂。
 */
export function croppedBack(g, { scarfAngle = 0.9, flutter = 0, rim = C.bone, body = C.deep } = {}) {
  const coat = [
    [1920, -120],
    [1892, 96],
    [1816, 236],
    [1748, 320],
    [1688, 372],
    [1596, 452],
    [1552, 560],
    [1538, 700],
    [1568, 862],
    [1612, 1000],
    [1642, 1080],
    [1920, 1080],
  ];
  const head = [1816, 168, 138];
  const bun = [1740, 238, 78];

  // 骨白版：整体偏 (-5,-3) —— 画面上只留左上一线，就是灯照出来的边
  g.save();
  g.translate(-5, -3);
  fillPoly(g, coat, rim, { amp: 2.2, seed: 21 });
  g.beginPath();
  g.arc(head[0], head[1], head[2], 0, Math.PI * 2);
  g.fillStyle = rim;
  g.fill();
  g.beginPath();
  g.arc(bun[0], bun[1], bun[2], 0, Math.PI * 2);
  g.fill();
  g.restore();

  // 墨版
  fillPoly(g, coat, body, { amp: 0, seed: 21 });
  g.beginPath();
  g.arc(head[0], head[1], head[2], 0, Math.PI * 2);
  g.fillStyle = body;
  g.fill();
  g.beginPath();
  g.arc(bun[0], bun[1], bun[2], 0, Math.PI * 2);
  g.fillStyle = C.ink;
  g.fill();
  // 发髻上的高光
  g.beginPath();
  g.arc(bun[0] - 22, bun[1] - 26, bun[2] * 0.66, Math.PI * 0.95, Math.PI * 1.55);
  g.strokeStyle = C.amberDim;
  g.lineWidth = 8;
  g.stroke();

  // 肩线上的钠光：一条实心黄
  g.strokeStyle = C.amber;
  g.lineWidth = 7;
  g.beginPath();
  g.moveTo(1578, 468);
  g.quadraticCurveTo(1660, 392, 1788, 300);
  g.stroke();

  // 围巾：脖子上一坨 + 两条尾巴（黄版先偏 4,-3 垫一层）
  const knot = [
    [1660, 330],
    [1728, 300],
    [1806, 318],
    [1836, 372],
    [1800, 424],
    [1716, 432],
    [1652, 400],
  ];
  const a1 = scarfAngle + flutter;
  const a2 = scarfAngle * 1.18 + 0.1 + flutter * 1.4;
  const t1 = tailPts(1672, 392, a1, 560, { n: 22, sag: 10 + 22 * Math.max(0, scarfAngle) });
  const t2 = tailPts(1666, 372, a2, 372, { n: 18, sag: 14 + 16 * Math.max(0, scarfAngle) });

  g.save();
  g.translate(4, -3);
  g.globalAlpha = 0.92;
  fillPoly(g, knot, C.amberDim, { amp: 2, seed: 5 });
  ribbon(g, t2, 40, 15, C.amberDim);
  g.restore();
  fillPoly(g, knot, C.bone, { amp: 2, seed: 5 });
  ribbon(g, t2, 38, 13, C.boneDim);
  ribbon(g, t1, 46, 18, C.bone);
  // 围巾上的折：一条黄的暗面细线
  const t3 = t1.map(([x, y], i) => [x, y + 7 - i * 0.12]);
  ribbon(g, t3.slice(4), 12, 5, C.amberDim, { alpha: 0.8 });
}

scenes._print.mjs:
// scenes/_print.mjs — 夜间丝网印（三块版）
//
// 这套画法只有三条规则：
//   1. 形是平涂块，硬边，不渐变、不模糊；
//   2. 光只用网点画（点大=亮，点小=暗）；网点 sprite 在 mount() 里预渲染；
//   3. 三块版对不准：骨白偏 (-3,-2)，钠黄偏 (+5,-3)，错开的地方露出底下的墨。
//
// 全片共用一个色板、一个纸边、一个套印偏移量。

export const W = 1920;
export const H = 1080;

export const C = {
  ink: '#12100f', // 墨：底
  deep: '#0a0908', // 更深的墨：洞、车体阴影
  struct: '#2a221e', // 结构中间调：墙
  structLite: '#2f2620', // 地面（比墙亮一点）
  flat: '#1a1512', // 车体、暗块
  grout: '#4a3a2d', // 瓷砖缝
  amber: '#f0a63c', // 钠黄：光
  amberDim: '#a4661f', // 黄版的暗面 / 套印鬼影
  bone: '#f4ecdd', // 骨白：亮边、纸、围巾、风痕
  boneDim: '#c9bda6', // 骨白的第二级
  red: '#8a2f22', // 哑红：只做小面积
  paper: '#b3a68f', // 印张的纸边
};

// --- 数 -------------------------------------------------------------------

export function mulberry32(a) {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const lerp = (a, b, p) => a + (b - a) * p;
export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const clamp01 = (v) => clamp(v, 0, 1);
export const smooth = (p) => {
  const x = clamp01(p);
  return x * x * (3 - 2 * x);
};
export const easeOut = (p) => 1 - (1 - clamp01(p)) ** 3;
export const easeInOut = (p) => {
  const x = clamp01(p);
  return x < 0.5 ? 4 * x * x * x : 1 - (-2 * x + 2) ** 3 / 2;
};
/** 0→1→0 的窗：rise 秒进，hold 秒停，fall 秒出。 */
export function win(t, at, rise = 0.2, hold = 0.4, fall = 0.3) {
  if (t < at) return 0;
  const d = t - at;
  if (d < rise) return smooth(d / rise);
  if (d < rise + hold) return 1;
  if (d < rise + hold + fall) return 1 - smooth((d - rise - hold) / fall);
  return 0;
}

// --- 网点 -----------------------------------------------------------------

/**
 * 一张网点光斑：中心点大、边缘点小，中心压一个实心的高光核。
 * 只建一次，render 里 drawImage —— 每帧不重算。
 */
export function makeGlow({
  w = 640,
  h = 640,
  step = 14,
  angle = 0.28,
  color = C.amber,
  hot = C.bone,
  hotR = 0.26,
  power = 0.62,
  jitter = 0.22,
  seed = 7,
} = {}) {
  const cv = document.createElement('canvas');
  cv.width = Math.ceil(w);
  cv.height = Math.ceil(h);
  const g = cv.getContext('2d');
  const rng = mulberry32(seed);
  const cx = w / 2;
  const cy = h / 2;
  const rx = w / 2;
  const ry = h / 2;
  const ca = Math.cos(angle);
  const sa = Math.sin(angle);
  g.fillStyle = color;
  const reach = Math.max(w, h);
  for (let gy = -reach; gy < reach * 2; gy += step) {
    for (let gx = -reach; gx < reach * 2; gx += step) {
      const dx0 = gx - cx;
      const dy0 = gy - cy;
      const x = cx + dx0 * ca - dy0 * sa;
      const y = cy + dx0 * sa + dy0 * ca;
      if (x < -step || y < -step || x > w + step || y > h + step) continue;
      const d = Math.hypot((x - cx) / rx, (y - cy) / ry);
      if (d >= 1) continue;
      // 边缘点随机缺席：光斑的边不能是一个规整的圆
      if (d > 0.78 && rng() < (d - 0.78) * 3.4) continue;
      const r = step * 0.73 * Math.pow(1 - d, power) * (1 + (rng() - 0.5) * jitter);
      if (r < 0.3) continue;
      g.beginPath();
      g.arc(x, y, r, 0, Math.PI * 2);
      g.fill();
    }
  }
  // 高光核：一块实心骨白，边缘故意留几个缺口（版子边）
  if (hotR > 0) {
    g.fillStyle = hot;
    g.beginPath();
    const n = 46;
    for (let i = 0; i <= n; i++) {
      const a = (i / n) * Math.PI * 2;
      const k = 1 + (rng() - 0.5) * 0.16;
      const px = cx + Math.cos(a) * rx * hotR * k;
      const py = cy + Math.sin(a) * ry * hotR * k;
      i ? g.lineTo(px, py) : g.moveTo(px, py);
    }
    g.closePath();
    g.fill();
  }
  return cv;
}

/** 把 sprite 的中心放在 (cx,cy)，缩放 s。 */
export function blit(g, cv, cx, cy, s = 1, alpha = 1) {
  if (alpha <= 0) return;
  g.save();
  g.globalAlpha *= alpha;
  g.drawImage(cv, cx - (cv.width * s) / 2, cy - (cv.height * s) / 2, cv.width * s, cv.height * s);
  g.restore();
}

/** 一张 k 倍大的底图；draw 用设计坐标 0..W / 0..H。 */
export function stillAt(ctx, k, draw) {
  return ctx.still((g) => draw(g), { scale: k });
}

/** 底图按镜头缩放贴回：z=1 原样，z>1 推近。 */
export function plate(g, base, { z = 1, cx = W / 2, cy = H / 2 } = {}) {
  g.save();
  g.translate(cx, cy);
  g.scale(z, z);
  g.translate(-cx, -cy);
  g.drawImage(base, 0, 0, W, H);
  g.restore();
}

// --- 形 -------------------------------------------------------------------

/** 带抖动的多边形：amp 是版子边的毛刺，不是装饰。 */
export function fillPoly(g, pts, color, { amp = 0, seed = 1, close = true } = {}) {
  const rng = mulberry32(seed);
  g.beginPath();
  pts.forEach(([x, y], i) => {
    const jx = amp ? (rng() - 0.5) * amp : 0;
    const jy = amp ? (rng() - 0.5) * amp : 0;
    i ? g.lineTo(x + jx, y + jy) : g.moveTo(x + jx, y + jy);
  });
  if (close) g.closePath();
  g.fillStyle = color;
  g.fill();
}

/** 锥形刀痕：风的基本笔画。 */
export function taper(g, x1, y1, x2, y2, w1, w2, color, alpha = 1) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const L = Math.hypot(dx, dy);
  if (L < 0.5) return;
  const nx = -dy / L;
  const ny = dx / L;
  g.save();
  g.globalAlpha *= alpha;
  g.beginPath();
  g.moveTo(x1 + (nx * w1) / 2, y1 + (ny * w1) / 2);
  g.lineTo(x2 + (nx * w2) / 2, y2 + (ny * w2) / 2);
  g.lineTo(x2 - (nx * w2) / 2, y2 - (ny * w2) / 2);
  g.lineTo(x1 - (nx * w1) / 2, y1 - (ny * w1) / 2);
  g.closePath();
  g.fillStyle = color;
  g.fill();
  g.restore();
}

/** 纸边：画面四周的印张出血线。全片一样宽。 */
export function paperEdge(g, w = 14) {
  g.fillStyle = C.paper;
  g.fillRect(0, 0, W, w);
  g.fillRect(0, H - w, W, w);
  g.fillRect(0, 0, w, H);
  g.fillRect(W - w, 0, w, H);
}

// --- 纸片 -----------------------------------------------------------------

/**
 * 一张纸：骨白的四边形 + 一道折痕 + 三行印上去的假字。
 * 折痕用黄的暗面，等于第二块版。
 */
export function scrap(g, x, y, s, rot = 0, flip = 1, { color = C.bone, ink = C.ink, fold = C.amberDim, squash = 1, lines = true } = {}) {
  g.save();
  g.translate(x, y);
  g.rotate(rot);
  g.scale(s, flip * s * squash);
  fillPoly(g, [
    [-50, -34],
    [50, -40],
    [44, 36],
    [-52, 30],
  ], color, { amp: 3, seed: 11 });
  fillPoly(g, [
    [10, -38],
    [50, -40],
    [44, 36],
  ], fold, { amp: 2, seed: 12 });
  if (lines) {
    g.strokeStyle = ink;
    g.lineWidth = 3;
    for (let i = 0; i < 2; i++) {
      g.beginPath();
      g.moveTo(-36, -14 + i * 18);
      g.lineTo(i === 1 ? 4 : 24, -14 + i * 18);
      g.stroke();
    }
  }
  g.restore();
}

scenes.platform.mjs:
// 第一镜 · 站台
//
// 物：黄线、立柱、吊灯、一张传单、一个纸杯、远处站着的背影。
// 动作：风先到——传单抖角、翻面、贴着地滚向镜头；纸杯滚半步；大衣下摆开始拍。
// 机位：低，一点透视，不动（只有 0.4% 的呼吸）。这一镜要让观众先认出台阶、黄线、等车的人。

import { W, H, C, mulberry32, clamp01, smooth, stillAt, plate, paperEdge, makeGlow, blit, taper, fillPoly } from './_print.mjs';
import { standBack } from './_figures.mjs';
import { scrap } from './_print.mjs';

export const id = 'platform';
export const slots = {};

const VP = { x: 960, y: 545 };
const EDGE_X = 1420; // 站台边缘线在画面底边的 x
const YEL_X = 1265; // 黄线内边在画面底边的 x
const WALL_END = 820; // 左墙在屏幕上的尽头
const JUNC_Y = 790; // 墙脚线在左边缘的 y
const CORN_Y = -300; // 檐口线在左边缘的 y
const LAMP = { x: 1180, y: 74 };

let ctx;
let base;
let glow;
let pool;
let farGlow;
let wash;
let dust;

// 透视：near 点连到灭点
const toVP = (x0, y0, atX) => {
  const k = (atX - x0) / (VP.x - x0);
  return [atX, y0 + (VP.y - y0) * k];
};
const edgeAt = (y) => 960 + ((EDGE_X - 960) * (y - VP.y)) / (1080 - VP.y);

export function mount(context) {
  ctx = context;
  const rng = mulberry32(90210);
  dust = Array.from({ length: 52 }, () => ({
    x0: 250 + rng() * 2300,
    y: 540 + rng() * 490,
    len: 24 + rng() * 120,
    sp: 240 + rng() * 660,
    w: 1.4 + rng() * 4.2,
    a: 0.2 + rng() * 0.42,
    t0: 0.86 + rng() * 1.6,
    tilt: (rng() - 0.5) * 0.14,
    amber: rng() < 0.16,
  }));
  glow = makeGlow({ w: 460, h: 460, step: 10, angle: 0.3, hotR: 0.2, seed: 3 });
  farGlow = makeGlow({ w: 150, h: 150, step: 8, hotR: 0.2, seed: 5 });
  wash = makeGlow({ w: 760, h: 640, step: 11, angle: 0.3, hotR: 0, power: 1.0, seed: 13 });
  pool = makeGlow({ w: 1120, h: 500, step: 9, angle: 0.28, hotR: 0, power: 1.15, seed: 9 });
  base = stillAt(ctx, 1.25, drawBase);
}

function wallPath(g) {
  g.beginPath();
  g.moveTo(0, CORN_Y);
  for (let x = 20; x <= WALL_END; x += 20) {
    const p = toVP(0, CORN_Y, x);
    g.lineTo(p[0], p[1]);
  }
  const j = toVP(0, JUNC_Y, WALL_END);
  g.lineTo(WALL_END, j[1]);
  g.lineTo(0, JUNC_Y);
  g.closePath();
}

function drawBase(g) {
  g.fillStyle = C.ink;
  g.fillRect(0, 0, W, H);

  // --- 地面：地平线以下、黄线以左 ---
  fillPoly(g, [[0, VP.y], [VP.x, VP.y], [EDGE_X, H], [0, H]], C.structLite, { amp: 0 });

  const rowY = [];
  for (let n = 0; n < 13; n++) rowY.push(VP.y + (H - VP.y) * Math.pow(0.78, n));

  // 地砖：几块被踩亮的平涂一档
  for (let r = 2; r < rowY.length - 2; r += 2) {
    for (let c = 1; c < 6; c += 3) {
      const x1 = 80 + c * 235;
      const x2 = x1 + 235;
      fillPoly(g, [[x1, rowY[r]], [x2, rowY[r]], [x2, rowY[r + 1]], [x1, rowY[r + 1]]], '#382d24', { amp: 0 });
    }
  }
  // 地砖缝：横线 + 连到灭点的纵线
  g.strokeStyle = C.ink;
  g.lineWidth = 2.2;
  for (const y of rowY) {
    g.beginPath();
    g.moveTo(0, y);
    g.lineTo(edgeAt(y) - 8, y);
    g.stroke();
  }
  for (let i = -1; i < 8; i++) {
    const x = 80 + i * 235;
    g.beginPath();
    g.moveTo(x, H + 20);
    g.lineTo(VP.x, VP.y);
    g.stroke();
  }

  // 远处压一档：光打不到的地方是平的暗，不是渐变
  g.save();
  g.globalAlpha = 0.28;
  fillPoly(g, [[0, VP.y], [VP.x, VP.y], [edgeAt(742), 742], [0, 742]], C.ink, { amp: 0 });
  g.restore();

  // --- 黄线 ---
  fillPoly(g, [[YEL_X, H], [YEL_X + 5, H], [VP.x, VP.y], [EDGE_X - 34, H], [EDGE_X - 44, H]], C.amber, { amp: 0 });
  g.save();
  g.translate(5, -3);
  g.globalAlpha = 0.5;
  fillPoly(g, [[YEL_X + 8, H], [YEL_X + 14, H], [VP.x, VP.y], [EDGE_X - 28, H], [EDGE_X - 38, H]], C.amberDim, { amp: 0 });
  g.restore();
  g.strokeStyle = C.bone;
  g.lineWidth = 4;
  g.beginPath();
  g.moveTo(EDGE_X, H);
  g.lineTo(VP.x, VP.y);
  g.stroke();
  g.strokeStyle = C.boneDim;
  g.lineWidth = 2;
  g.beginPath();
  g.moveTo(YEL_X + 2, H);
  g.lineTo(VP.x, VP.y);
  g.stroke();

  // --- 吊灯在地上的光池 ---
  blit(g, pool, 1120, 950, 1, 0.34);

  // --- 左墙 ---
  wallPath(g);
  g.fillStyle = C.struct;
  g.fill();
  // 远处两盏灯打在墙上的光（裁在墙面里）
  g.save();
  wallPath(g);
  g.clip();
  blit(g, wash, 770, 500, 1, 0.3);
  g.restore();
  // 墙砖：竖缝
  g.strokeStyle = C.grout;
  g.lineWidth = 2;
  for (let n = 0; n < 22; n++) {
    const x = VP.x - (VP.x + 80) * Math.pow(0.865, n);
    if (x > WALL_END) break;
    const [, yTop] = toVP(0, CORN_Y, x);
    const [, yBot] = toVP(0, JUNC_Y, x);
    g.beginPath();
    g.moveTo(x, yTop);
    g.lineTo(x, yBot);
    g.stroke();
  }
  // 墙砖：横缝
  for (let y = CORN_Y; y <= JUNC_Y + 0.1; y += 108) {
    const [, ye] = toVP(0, y, WALL_END);
    g.beginPath();
    g.moveTo(0, y);
    g.lineTo(WALL_END, ye);
    g.stroke();
  }
  // 墙上的红带（腰线）
  fillPoly(g, [[0, 300], [WALL_END, toVP(0, 300, WALL_END)[1]], [WALL_END, toVP(0, 352, WALL_END)[1]], [0, 352]], C.red, { amp: 0 });
  // 檐口 + 墙脚
  g.strokeStyle = C.boneDim;
  g.lineWidth = 3;
  g.beginPath();
  g.moveTo(0, CORN_Y);
  g.lineTo(...toVP(0, CORN_Y, WALL_END));
  g.stroke();
  g.beginPath();
  g.moveTo(0, JUNC_Y);
  g.lineTo(...toVP(0, JUNC_Y, WALL_END));
  g.stroke();

  // --- 轨行区 ---
  fillPoly(g, [[VP.x, VP.y], [W, VP.y], [W, H], [EDGE_X, H]], '#0d0a09', { amp: 0 });
  // 两条钢轨：从灭点向右下展开
  taper(g, VP.x + 6, VP.y + 8, W + 30, 872, 2, 8, C.amberDim, 0.85);
  taper(g, VP.x + 6, VP.y + 12, W + 30, 964, 2, 7, C.boneDim, 0.5);

  // --- 对面站台：一条边线、一条黄线、一堵暗墙 ---
  for (const [y2, col, w] of [[800, C.boneDim, 3], [762, C.amber, 6]]) {
    taper(g, VP.x, VP.y + 2, W + 10, y2, 1.5, w, col, 0.75);
  }
  fillPoly(g, [[VP.x, VP.y], [W, VP.y], [W, 800], [VP.x, VP.y]], '#1b1613', { amp: 0 });
  fillPoly(g, [[VP.x, VP.y], [W, VP.y], [W, 330], [VP.x, VP.y]], '#17120f', { amp: 0 });
  // 对面墙上的砖缝、红带、瓷砖
  g.save();
  g.beginPath();
  g.moveTo(VP.x, VP.y);
  g.lineTo(W, VP.y);
  g.lineTo(W, 320);
  g.closePath();
  g.clip();
  g.strokeStyle = '#2a211c';
  g.lineWidth = 1.6;
  for (let n = 0; n < 16; n++) {
    const x = W - 4 - 420 * (1 - Math.pow(0.82, n));
    g.beginPath();
    g.moveTo(x, 320 + 225 * ((x - VP.x) / (W - VP.x)) ** 0.0 * 0);
    g.lineTo(x, 760);
    g.stroke();
  }
  // 对面墙的红带
  fillPoly(g, [[VP.x, VP.y + 2], [W, 560], [W, 596], [VP.x, VP.y + 2]], '#5c231a', { amp: 0 });
  g.restore();

  // --- 近处的立柱 ---
  fillPoly(g, [[22, -120], [214, -114], [222, 930], [12, 924]], C.flat, { amp: 3, seed: 71 });
  g.fillStyle = C.boneDim;
  g.fillRect(206, -112, 6, 1034);
  fillPoly(g, [[22, 300], [222, 318], [222, 352], [22, 334]], C.red, { amp: 0 });
  // 中景的两根柱子
  for (const [x, w, top, bot] of [[455, 58, 356, 663], [590, 36, 402, 616], [680, 24, 432, 585]]) {
    fillPoly(g, [[x, top], [x + w, top + 3], [x + w + 3, bot], [x, bot - 2]], C.flat, { amp: 2, seed: x });
    g.fillStyle = C.boneDim;
    g.fillRect(x + w - 1, top + 4, 3, bot - top - 8);
  }

  // --- 吊灯：一盏钠灯。灯管是一根实心黄，光晕在它后面 ---
  blit(g, glow, LAMP.x, 176, 0.46, 0.95);
  g.fillStyle = C.boneDim;
  g.fillRect(LAMP.x - 1, 0, 3, 72);
  fillPoly(g, [[LAMP.x - 96, 72], [LAMP.x + 96, 72], [LAMP.x + 124, 110], [LAMP.x - 124, 110]], C.ink, { amp: 2, seed: 89 });
  g.fillStyle = C.amber;
  g.fillRect(LAMP.x - 122, 108, 244, 12);
  g.fillStyle = C.bone;
  g.fillRect(LAMP.x - 122, 108, 244, 4);
  // 远一点的两盏
  for (const [x, y, sc] of [[706, 300, 0.2], [820, 392, 0.12]]) {
    g.fillStyle = C.boneDim;
    g.fillRect(x - 1, y - 60, 2, 60);
    blit(g, farGlow, x, y, sc, 0.9);
  }
  // 对面站台的两盏小灯
  for (const [x, y, sc] of [[1580, 588, 0.13], [1792, 636, 0.1]]) {
    blit(g, farGlow, x, y, sc, 0.8);
  }
}

function drawCup(g, x, y, rot, s = 1) {
  g.save();
  g.translate(x, y);
  g.rotate(rot);
  g.scale(s, s);
  // 杯身
  g.fillStyle = C.bone;
  g.beginPath();
  g.moveTo(-24, -19);
  g.lineTo(22, -16);
  g.quadraticCurveTo(30, 0, 22, 16);
  g.lineTo(-24, 19);
  g.closePath();
  g.fill();
  // 印刷的带子
  g.fillStyle = C.amberDim;
  g.fillRect(-6, -18, 7, 36);
  // 杯口
  g.beginPath();
  g.ellipse(-24, 0, 8, 19, 0, 0, Math.PI * 2);
  g.fillStyle = C.boneDim;
  g.fill();
  g.beginPath();
  g.ellipse(-24, 0, 5.5, 14, 0, 0, Math.PI * 2);
  g.fillStyle = C.ink;
  g.fill();
  g.restore();
}

export function render(t) {
  const g = ctx.canvas.getContext('2d');
  const breathe = 1 + 0.004 * Math.sin(t * 1.6 + 0.4);
  plate(g, base, { z: breathe, cx: 990, cy: 700 });

  const wind = smooth((t - 0.75) / 1.5);

  // --- 风里的尘和纸屑 ---
  for (const d of dust) {
    const age = t - d.t0;
    if (age <= 0) continue;
    const x = d.x0 - age * d.sp;
    if (x < -260 || x > W + 120) continue;
    const y = d.y + (d.x0 - x) * d.tilt;
    const a = d.a * clamp01(age / 0.35) * (0.55 + 0.45 * wind);
    taper(g, x + d.len, y + d.len * d.tilt * 0.5, x, y, d.w * 0.55, d.w, d.amber ? C.amber : C.bone, a);
  }

  // --- 几道长的风痕：比尘更长的刀口 ---
  for (let i = 0; i < 7; i++) {
    const sp = 700 + i * 130;
    const y = 470 + ((i * 173) % 470);
    const t0 = 1.0 + i * 0.16;
    const age = t - t0;
    if (age <= 0) continue;
    const x = 1900 - age * sp * 1.15 + i * 90;
    const len = 190 + i * 40;
    const a = 0.1 + 0.16 * clamp01(age / 0.5) * (1 - clamp01(age / 2.4));
    taper(g, x + len, y + 6, x, y, 1.2, 3.4, C.bone, a);
  }

  // --- 远处的车头灯：两点黄，先来 ---
  const pin = smooth((t - 2.15) / 0.55);
  if (pin > 0) {
    for (const [x, y, s] of [
      [928, 578, 0.1],
      [962, 578, 0.1],
    ]) {
      blit(g, farGlow, x, y, s * (0.7 + pin * 0.6), 0.55 + 0.45 * pin);
    }
  }

  // --- 纸杯：被风推着滚半步 ---
  const cupRun = clamp01((t - 1.1) / 1.35);
  const cupX = 828 - 104 * easeOutSoft(cupRun);
  g.save();
  g.globalAlpha = 0.45;
  g.beginPath();
  g.ellipse(cupX, 1012 + 2 * cupRun, 52, 11, 0, 0, Math.PI * 2);
  g.fillStyle = C.ink;
  g.fill();
  g.restore();
  drawCup(g, cupX, 984 + 2 * cupRun, -0.3 * cupRun, 1.35);

  // --- 传单：抖角 → 翻面 → 贴着地滚向镜头 ---
  const lift = smooth((t - 0.45) / 0.7);
  if (t < 1.15) {
    g.save();
    g.globalAlpha = 0.4;
    fillPoly(g, [[492, 880], [644, 872], [650, 900], [500, 908]], C.ink, { amp: 0 });
    g.restore();
    drawFlyer(g, 566, 852, 0.78, -0.05 * lift, 1, 1 - 0.12 * lift, 0.5);
  } else {
    const p = clamp01((t - 1.15) / 1.45);
    const q = p * p * (0.72 + 0.28 * p);
    const x = lerpQ(566, 400, 30, q);
    const y = lerpQ(852, 500, 1210, q);
    const s = 0.78 + 1.15 * q;
    const rot = 6.4 * q;
    const flip = Math.cos(2.7 * Math.PI * q);
    drawFlyer(g, x, y, s, rot, flip, 1);
  }

  // --- 等车的人：站在黄线上，风把围巾从左肩吹横 ---
  const windLift = smooth((t - 1.25) / 1.3);
  const scarfAngle = 0.95 - 0.86 * windLift + 0.05 * Math.sin(t * 15) * windLift;
  standBack(g, { x: 1210, feetY: 930, h: 340, scarfAngle, sway: 0.3 * wind });

  paperEdge(g);
}

const lerpQ = (a, b, c, p) => (1 - p) * (1 - p) * a + 2 * (1 - p) * p * b + p * p * c;
const easeOutSoft = (p) => 1 - (1 - clamp01(p)) ** 2;

function drawFlyer(g, x, y, s, rot, flip, alpha, squash = 1) {
  g.save();
  g.globalAlpha = alpha;
  scrap(g, x, y, s, rot, flip, { squash });
  g.restore();
}

scenes.scarf.mjs:
// 第四镜 · 风停
//
// 物：肩、大衣的一大块暗面、一条搭在肩上的围巾。
// 动作：围巾从横着绷直的状态松掉，摆两下，落回肩上；一点纸屑慢慢飘下去。
// 机位：肩部特写（脖子以上裁在画外），缓拉 1.06→1.00。光从左边那扇刚开的门里来。

import {
  W, H, C, mulberry32, clamp01, smooth, lerp,
  stillAt, plate, paperEdge, makeGlow, blit, fillPoly,
} from './_print.mjs';
import { ribbon, tailPts } from './_figures.mjs';

export const id = 'scarf';
export const slots = {};

// 大衣的肩线：从画面左下升到右上
const COAT = [
  [0, 1080],
  [260, 972],
  [560, 902],
  [860, 842],
  [1140, 772],
  [1360, 682],
  [1520, 562],
  [1634, 452],
  [1742, 424],
  [1822, 524],
  [1884, 724],
  [1920, 904],
  [1920, 1080],
];
const NECK = [
  [1622, 462],
  [1698, 300],
  [1812, 330],
  [1748, 478],
];
const HEAD = [1858, 186, 176];
const BUN = [1924, 96, 112];

let ctx;
let base;
let doorGlow;
let specks;

export function mount(context) {
  ctx = context;
  const rng = mulberry32(808);
  specks = Array.from({ length: 7 }, () => ({
    x: 700 + rng() * 900,
    y: -80 + rng() * 800,
    v: 35 + rng() * 70,
    s: 2 + rng() * 5,
    a: 0.18 + rng() * 0.3,
    t0: rng() * 1.5,
    amber: rng() < 0.4,
  }));
  doorGlow = makeGlow({ w: 340, h: 1100, step: 12, hotR: 0, power: 1.15, seed: 71 });
  base = stillAt(ctx, 1.22, drawBg);
}

function drawBg(g) {
  g.fillStyle = '#17120f';
  g.fillRect(0, 0, W, H);
  // 车体：比大衣亮一档的暗面，几道竖缝
  g.fillStyle = '#2a221d';
  g.fillRect(250, 0, W - 250, H);
  g.fillStyle = '#1d1714';
  for (let x = 320; x < W; x += 244) g.fillRect(x, 0, 4, H);
  g.fillStyle = '#1d1714';
  g.fillRect(250, 128, W - 250, 5);
  g.fillRect(250, 806, W - 250, 5);
  // 墙上的瓷砖缝：很淡
  g.strokeStyle = '#33291f';
  g.lineWidth = 2;
  for (let y = 40; y < H; y += 132) {
    g.beginPath();
    g.moveTo(250, y);
    g.lineTo(W, y);
    g.stroke();
  }
  // 门框：左边那扇刚开的门
  g.fillStyle = C.ink;
  g.fillRect(66, 0, 270, H);
  g.fillStyle = '#241d1a';
  g.fillRect(66, 0, 22, H);
  g.fillRect(314, 0, 26, H);
  g.fillStyle = C.boneDim;
  g.fillRect(88, 0, 3, H);
  g.fillRect(311, 0, 3, H);
  g.fillStyle = C.red;
  g.fillRect(96, 0, 9, H);
}

export function render(t) {
  const g = ctx.canvas.getContext('2d');
  const z = lerp(1.06, 1.0, smooth(t / 2.0));
  plate(g, base, { z, cx: 1100, cy: 640 });

  // --- 门里的光：亮一下（提示音），然后慢慢收 ---
  const pulse = smooth(t / 0.3) * (1 - smooth((t - 0.55) / 1.35));
  blit(g, doorGlow, 210, 540, 1, 0.46 + 0.32 * pulse);
  g.save();
  g.globalAlpha = 0.3 + 0.5 * (0.55 + 0.45 * pulse);
  g.fillStyle = C.amber;
  g.fillRect(140, 54, 132, H - 108);
  g.restore();
  g.fillStyle = C.bone;
  g.fillRect(190, 40, 12, H - 80);
  g.save();
  g.globalAlpha = 0.55;
  g.fillStyle = C.boneDim;
  g.fillRect(202, 40, 4, H - 80);
  g.restore();
  // 门框边上被光照到的一线
  g.save();
  g.globalAlpha = 0.75;
  g.fillStyle = C.amberDim;
  g.fillRect(314, 0, 6, H);
  g.restore();

  // --- 人：肩、脖子、后脑（裁在画外） ---
  const bob = 1.5 * Math.sin(t * 2.2 + 0.4);
  g.save();
  g.translate(0, bob);

  // 骨白版：整体偏 (-7,-4)，压完墨只剩左上一线
  g.save();
  g.translate(-7, -4);
  fillPoly(g, COAT, C.bone, { amp: 3.2, seed: 23 });
  fillPoly(g, NECK, C.bone, { amp: 2, seed: 24 });
  g.beginPath();
  g.arc(HEAD[0], HEAD[1], HEAD[2], 0, Math.PI * 2);
  g.fillStyle = C.bone;
  g.fill();
  g.beginPath();
  g.arc(BUN[0], BUN[1], BUN[2], 0, Math.PI * 2);
  g.fill();
  g.restore();

  fillPoly(g, COAT, '#100d0b', { amp: 0, seed: 23 });
  fillPoly(g, NECK, '#151110', { amp: 0, seed: 24 });
  g.beginPath();
  g.arc(HEAD[0], HEAD[1], HEAD[2], 0, Math.PI * 2);
  g.fillStyle = '#141010';
  g.fill();
  g.beginPath();
  g.arc(BUN[0], BUN[1], BUN[2], 0, Math.PI * 2);
  g.fillStyle = '#0d0b0a';
  g.fill();
  // 发髻上的一道钠光
  g.beginPath();
  g.arc(BUN[0] - 20, BUN[1] - 20, BUN[2] * 0.7, Math.PI * 0.85, Math.PI * 1.5);
  g.strokeStyle = C.amberDim;
  g.lineWidth = 10;
  g.stroke();

  // 衣领：比大衣亮一档的一条带子，压出肩颈
  const collar = [
    [1500, 590],
    [1580, 500],
    [1660, 438],
    [1750, 430],
    [1772, 500],
    [1690, 548],
    [1610, 610],
  ];
  fillPoly(g, collar, '#1c1613', { amp: 2, seed: 31 });
  g.strokeStyle = C.boneDim;
  g.lineWidth = 3;
  g.beginPath();
  g.moveTo(1500, 590);
  g.lineTo(1580, 500);
  g.lineTo(1660, 438);
  g.lineTo(1750, 430);
  g.stroke();
  // 大衣的缝线
  g.strokeStyle = '#241d19';
  g.lineWidth = 4;
  g.beginPath();
  g.moveTo(1050, 800);
  g.quadraticCurveTo(1180, 930, 1240, 1080);
  g.stroke();
  // 肩线上一道钠黄：门光擦过
  g.strokeStyle = C.amber;
  g.lineWidth = 9;
  g.beginPath();
  g.moveTo(600, 900);
  g.quadraticCurveTo(1100, 800, 1520, 566);
  g.stroke();

  // --- 围巾：搭在肩上，尾端从横着绷直 → 摆两下 → 落下 ---
  const drape = [
    [1920, 300],
    [1850, 336],
    [1780, 372],
    [1712, 404],
  ];
  const fall = (target, delay, k, w) => {
    const tt = Math.max(0, t - delay);
    const start = 0.04;
    return target + (start - target) * Math.exp(-k * tt) * Math.cos(w * tt);
  };
  const a1 = fall(1.06, 0.0, 3.15, 5.1) + 0.012 * Math.sin(t * 7.2) * Math.max(0, 1 - t);
  const tip = tailPts(1690, 432, a1, 700, { n: 28, sag: 34 * Math.max(0, a1) });

  // 黄版：偏 (5,-3)
  g.save();
  g.translate(5, -3);
  g.globalAlpha = 0.9;
  ribbon(g, drape, 104, 96, C.amberDim);
  ribbon(g, tip, 88, 28, C.amberDim);
  g.restore();
  // 骨白版
  ribbon(g, drape, 100, 92, C.bone);
  ribbon(g, tip, 84, 26, C.bone);
  // 围巾的折：一条黄的暗面
  const fold = tip.map(([x, y], i) => [x + 4, y + 18 - i * 0.22]);
  ribbon(g, fold.slice(3), 18, 8, C.amberDim, { alpha: 0.9 });
  const fold2 = drape.map(([x, y]) => [x - 4, y + 26]);
  ribbon(g, fold2, 14, 12, C.amberDim, { alpha: 0.8 });
  // 在脖子上绕的那一圈
  const knot = [
    [1612, 396],
    [1688, 360],
    [1768, 376],
    [1794, 436],
    [1738, 484],
    [1650, 486],
    [1600, 446],
  ];
  g.save();
  g.translate(5, -3);
  g.globalAlpha = 0.9;
  fillPoly(g, knot, C.amberDim, { amp: 3, seed: 7 });
  g.restore();
  fillPoly(g, knot, C.bone, { amp: 3, seed: 7 });

  g.restore();

  // --- 一点纸屑慢慢飘下去 ---
  for (const s of specks) {
    const age = t - s.t0;
    if (age <= 0) continue;
    const y = s.y + s.v * age;
    const x = s.x + 24 * Math.sin(age * 1.7 + s.x * 0.01);
    if (y > H + 40) continue;
    g.save();
    g.globalAlpha = s.a * clamp01(age / 0.3);
    g.fillStyle = s.amber ? C.amber : C.bone;
    g.beginPath();
    g.arc(x, y, s.s, 0, Math.PI * 2);
    g.fill();
    g.restore();
  }

  paperEdge(g);
}

scenes.train.mjs:
// 第三镜 · 车过
//
// 物：车厢侧面——车窗、门缝、腰线、黄线；还有一张被风卷过来的传单。
// 动作：车体从右向左横扫、减速、停住；门缝在最后一刻亮起一条黄。
// 机位：平视，跟车横移（镜头有震动，车停震动就停）。

import {
  W, H, C, mulberry32, clamp01, smooth, easeOut,
  stillAt, paperEdge, makeGlow, blit, taper, fillPoly, scrap,
} from './_print.mjs';
import { ribbon, tailPts } from './_figures.mjs';

export const id = 'train';
export const slots = {};

const TOP = 150;
const BOT = 900;
const UNIT = 1200; // 一个重复单元：3 扇窗 + 1 樘门
const DOOR_X = 810;
const STOP_T = 2.52;
const D = 4930; // 停住时累计位移，正好把一樘门停在 780

let ctx;
let base;
let pattern;
let doorGlow;
let dust;

export function mount(context) {
  ctx = context;
  const rng = mulberry32(3131);
  dust = Array.from({ length: 22 }, () => ({
    x0: 300 + rng() * 2400,
    y: 200 + rng() * 680,
    sp: 1500 + rng() * 1500,
    len: 40 + rng() * 130,
    w: 2 + rng() * 5,
    a: 0.1 + rng() * 0.3,
    t0: rng() * 1.8,
    amber: rng() < 0.5,
  }));
  // 窗的光：一块网点
  const tile = document.createElement('canvas');
  tile.width = 22;
  tile.height = 22;
  const tg = tile.getContext('2d');
  tg.fillStyle = C.amber;
  tg.beginPath();
  tg.arc(11, 11, 5.2, 0, Math.PI * 2);
  tg.fill();
  pattern = ctx.canvas.getContext('2d').createPattern(tile, 'repeat');
  doorGlow = makeGlow({ w: 260, h: 900, step: 13, hotR: 0, power: 1.1, seed: 61 });
  base = stillAt(ctx, 1.22, drawBg);
}

const offset = (t) => D * (1 - (1 - clamp01(t / STOP_T)) ** 3);
const speed = (t) => (3 * D) / STOP_T * (1 - clamp01(t / STOP_T)) ** 2;

function drawBg(g) {
  g.fillStyle = C.ink;
  g.fillRect(0, 0, W, H);
  // 上：站台的顶
  g.fillStyle = '#17120f';
  g.fillRect(0, 0, W, TOP);
  g.fillStyle = C.boneDim;
  g.fillRect(0, TOP - 4, W, 3);
  // 下：站台地面
  g.fillStyle = '#33291f';
  g.fillRect(0, BOT, W, H - BOT);
  g.fillStyle = C.ink;
  g.fillRect(0, BOT, W, 4);
  g.fillStyle = '#6b2a1f';
  g.fillRect(0, BOT + 6, W, 10);
  g.fillStyle = C.bone;
  g.fillRect(0, BOT + 16, W, 3);
  g.save();
  g.globalAlpha = 0.72;
  g.fillStyle = C.amber;
  g.fillRect(0, BOT + 58, W, 13);
  g.restore();
  g.fillStyle = C.ink;
  g.fillRect(0, BOT + 71, W, 3);
  g.fillStyle = '#241d1a';
  g.fillRect(0, BOT + 104, W, 3);
}

function windowAt(g, x, t, sp) {
  const y = 248;
  const w = 220;
  const h = 242;
  if (x + w < -260 || x > W + 260) return;
  const smear = sp * 0.055;
  if (smear > 6) {
    g.save();
    g.globalAlpha = 0.18;
    g.fillStyle = C.amber;
    g.fillRect(x + w - 10, y + 14, smear, h - 28);
    g.restore();
  }
  g.save();
  g.beginPath();
  g.rect(x, y, w, h);
  g.clip();
  // 车里的光：一块暗底 + 一层网点 + 顶部更亮的一条
  g.fillStyle = '#38220c';
  g.fillRect(x, y, w, h);
  g.globalAlpha = 0.9;
  g.fillStyle = pattern;
  g.fillRect(x, y, w, h);
  g.globalAlpha = 1;
  g.fillStyle = '#6b3f12';
  g.fillRect(x, y, w, 26);
  // 两根立杆
  g.fillStyle = '#2a1a0a';
  g.fillRect(x + 38, y + 6, 7, h - 12);
  g.fillRect(x + w - 45, y + 6, 7, h - 12);
  // 椅背（两个人）
  g.fillStyle = '#241708';
  for (let i = 0; i < 2; i++) {
    const sx = x + 20 + i * 100;
    g.beginPath();
    g.moveTo(sx, y + h - 4);
    g.lineTo(sx, y + h - 74);
    g.quadraticCurveTo(sx + 44, y + h - 96, sx + 88, y + h - 74);
    g.lineTo(sx + 88, y + h - 4);
    g.closePath();
    g.fill();
  }
  // 窗台
  g.fillStyle = '#1a1108';
  g.fillRect(x, y + h - 14, w, 14);
  g.restore();
  g.strokeStyle = C.bone;
  g.lineWidth = 2.6;
  g.strokeRect(x + 1.3, y + 1.3, w - 2.6, h - 2.6);
}

function doorAt(g, x, t) {
  const w = 200;
  if (x + w < -320 || x > W + 320) return;
  // 门板：比车体亮一点点，两道骨白的边
  g.fillStyle = '#221b17';
  g.fillRect(x, TOP + 6, w, BOT - TOP - 12);
  g.fillStyle = C.bone;
  g.fillRect(x + 1, TOP + 10, 3, BOT - TOP - 20);
  g.fillRect(x + w - 4, TOP + 10, 3, BOT - TOP - 20);
  // 门上的窗
  const dy = 268;
  const dw = w - 34;
  g.save();
  g.beginPath();
  g.rect(x + 17, dy, dw, 150);
  g.clip();
  g.fillStyle = '#38220c';
  g.fillRect(x + 17, dy, dw, 150);
  g.globalAlpha = 0.85;
  g.fillStyle = pattern;
  g.fillRect(x + 17, dy, dw, 150);
  g.globalAlpha = 1;
  g.fillStyle = '#2a1a0a';
  g.fillRect(x + 76, dy + 4, 7, 142);
  g.restore();
  g.strokeStyle = C.bone;
  g.lineWidth = 2.4;
  g.strokeRect(x + 18.2, dy + 1.2, dw - 2.4, 147.6);
  // 门上方的到站显示：三个黄点（不是字）
  g.fillStyle = '#0f0c0b';
  g.fillRect(x + 56, 196, 88, 26);
  g.fillStyle = C.amber;
  for (let i = 0; i < 3; i++) {
    g.beginPath();
    g.arc(x + 76 + i * 22, 209, 5.5, 0, Math.PI * 2);
    g.fill();
  }
  // 门缝：一条黄，最后亮起来
  const lit = smooth((t - 2.56) / 0.34);
  const mx = x + w / 2;
  g.save();
  g.globalAlpha = 0.1 + 0.9 * lit;
  g.fillStyle = C.amber;
  g.fillRect(mx - 3, TOP + 18, 6, BOT - TOP - 36);
  g.restore();
  // 门的胶条：红
  g.fillStyle = '#5c231a';
  g.fillRect(x + 8, 440, w - 16, 7);
  g.fillRect(x + 8, 720, w - 16, 7);
}

/**
 * 右缘一个背影：肩、后脑的一角、一条被风扯向左侧的围巾。
 * 车在后面过，她在前面站着——这一镜靠她给纵深，也靠她的围巾把风画出来。
 */
function foreground(g, t) {
  // 只到肩：头裁在画外，右下一个大的暗面 + 一条往左甩的围巾
  const body = [
    [1920, 496],
    [1868, 540],
    [1812, 638],
    [1768, 792],
    [1730, 962],
    [1706, 1080],
    [1920, 1080],
  ];
  g.save();
  g.translate(-7, -4);
  fillPoly(g, body, C.bone, { amp: 2.6, seed: 51 });
  g.restore();
  fillPoly(g, body, '#0e0b0a', { amp: 0, seed: 51 });

  // 围巾：从画右伸进来，被风扯向左边，一直在抖
  const a = 0.13 + 0.05 * Math.sin(t * 9.3) + 0.03 * Math.sin(t * 17.1 + 1);
  const pts = tailPts(1912, 556, a, 620, { n: 22, sag: 30 });
  g.save();
  g.translate(4, -3);
  g.globalAlpha = 0.9;
  ribbon(g, pts, 56, 20, C.amberDim);
  g.restore();
  ribbon(g, pts, 52, 18, C.bone);
  const fold = pts.map(([x, y], i) => [x, y + 11 - i * 0.2]);
  ribbon(g, fold.slice(3), 13, 6, C.amberDim, { alpha: 0.85 });
  // 肩上的钠光
  g.strokeStyle = C.amber;
  g.lineWidth = 6;
  g.beginPath();
  g.moveTo(1716, 1040);
  g.quadraticCurveTo(1760, 780, 1846, 560);
  g.stroke();
}

export function render(t) {
  const g = ctx.canvas.getContext('2d');
  const sp = speed(t);
  const s = offset(t);
  const shakeY = 2.4 * (sp / 5000) * Math.sin(t * 91);
  const shakeX = 0.9 * (sp / 5000) * Math.sin(t * 57 + 1.1);

  g.save();
  g.translate(shakeX, shakeY);
  g.drawImage(base, 0, 0, W, H);

  // --- 车体：一条带子，只滚它 ---
  g.save();
  g.beginPath();
  g.rect(0, TOP, W, BOT - TOP);
  g.clip();
  g.fillStyle = '#191412';
  g.fillRect(0, TOP, W, BOT - TOP);

  const doorX = [];
  const k0 = Math.floor(s / UNIT) - 1;
  for (let k = k0; k <= k0 + 4; k++) {
    const ox = k * UNIT - s;
    for (let i = 0; i < 4; i++) windowAt(g, ox + 60 + i * 300, t, sp);
    doorAt(g, ox + DOOR_X, t);
    doorX.push(ox + DOOR_X);
    // 单元接缝 + 下裙板上的两道竖缝
    g.fillStyle = '#0e0b0a';
    g.fillRect(ox, TOP + 4, 5, BOT - TOP - 8);
    g.fillStyle = '#2c231d';
    g.fillRect(ox + 5, TOP + 4, 3, BOT - TOP - 8);

  }

  // 窗台线、裙板、腰线、顶部反光
  g.fillStyle = C.boneDim;
  g.fillRect(0, 500, W, 2.5);
  // 裙板：比车体亮一档，上面一道划痕
  g.fillStyle = '#211a16';
  g.fillRect(0, 716, W, BOT - 716);
  g.fillStyle = '#2a211c';
  g.fillRect(0, 716, W, 3);
  g.fillStyle = C.boneDim;
  g.fillRect(0, 812, W, 2);
  // 腰线：一条哑红，压在裙板上
  g.fillStyle = C.red;
  g.fillRect(0, 836, W, 16);
  g.fillStyle = C.amber;
  g.fillRect(0, TOP + 18, W, 2);
  g.fillStyle = C.bone;
  g.fillRect(0, BOT - 6, W, 3);
  // 裙板上跟着车一起走的竖缝和一排铆钉
  const kk0 = Math.floor(s / 300) - 1;
  for (let kk = kk0; kk <= kk0 + Math.ceil(W / 300) + 2; kk++) {
    const x = kk * 300 - s;
    g.fillStyle = '#2a211c';
    g.fillRect(x, 510, 2, 206);
    g.fillRect(x, 722, 2, 108);
  }
  g.fillStyle = '#3a2e25';
  for (let kk = kk0; kk <= kk0 + Math.ceil(W / 150) + 2; kk++) {
    const x = kk * 150 - s + 40;
    g.fillRect(x, 690, 4, 4);
  }

  // 速度线：贴着车窗底的一条条
  if (sp > 120) {
    const n = Math.min(16, Math.round(sp / 320));
    for (let i = 0; i < n; i++) {
      const y = 530 + ((i * 97) % 60);
      const x = (i * 211 - s * 1.02) % (W + 400);
      const px = x < -200 ? x + W + 400 : x;
      taper(g, px + 150 + sp * 0.02, y, px, y, 1.5, 4, C.amberDim, 0.5);
    }
  }
  g.restore();

  // --- 门缝的光晕（车停之后）---
  const lit = smooth((t - 2.56) / 0.34);
  if (lit > 0) {
    const target = doorX.reduce((best, x) => (Math.abs(x + 84 - 810) < Math.abs(best + 84 - 810) ? x : best), doorX[0]);
    g.save();
    g.beginPath();
    g.rect(0, TOP, W, BOT - TOP);
    g.clip();
    blit(g, doorGlow, target + 84, 540, 1, 0.5 * lit);
    g.restore();
    // 门缝的光落到地上
    g.save();
    g.globalAlpha = 0.18 * lit;
    g.fillStyle = C.amber;
    g.fillRect(target + 40, BOT + 72, 90, 5);
    g.restore();
  }

  // --- 前景：右缘的背影 ---
  foreground(g, t);

  // --- 风：从车前面卷过去的长痕 ---
  const wind = smooth((t - 0.15) / 0.9) * (1 - smooth((t - 2.2) / 0.7));
  for (const d of dust) {
    const age = t - d.t0;
    if (age <= 0) continue;
    const x = d.x0 - age * d.sp;
    if (x < -320 || x > W + 120) continue;
    const y = d.y - age * 40;
    const a = d.a * clamp01(age / 0.3) * wind;
    taper(g, x + d.len, y + 8, x, y, d.w * 0.3, d.w, d.amber ? C.amber : C.bone, a);
  }

  // --- 传单：从右边卷过来，贴着车身滑走 ---
  const fp = clamp01((t - 1.32) / 1.05);
  if (fp > 0 && fp < 1) {
    const x = 2050 - 2350 * easeOut(fp);
    const y = 420 + 120 * Math.sin(fp * 3.1);
    scrap(g, x, y, 1.15 + 0.6 * fp, -1.2 + 7 * fp, Math.cos(fp * 7.5), { lines: false });
  }

  g.restore();
  paperEdge(g);
}

scenes.tunnel.mjs:
// 第二镜 · 隧道口
//
// 物：隧道口、两盏车头灯、被风从洞里推出来的纸屑和尘土。
// 动作：黑洞口里的两点黄从针尖涨成两团网点，把瓷砖一圈圈点亮；纸屑朝镜头冲出来，
//       最后黑色的车头从光里长出来。
// 机位：正对洞口，缓推 1.00→1.10。

import {
  W, H, C, mulberry32, clamp01, smooth, easeInOut,
  stillAt, plate, paperEdge, makeGlow, blit, taper, fillPoly, scrap,
} from './_print.mjs';

export const id = 'tunnel';
export const slots = {};

const MOUTH = { x: 920, top: 300, bottom: 960, halfW: 330 };
const PIT_TOP = 960;
const EDGE_TOP = 1002;
const YEL_TOP = 1024;

let ctx;
let base;
let pinGlow;
let wash;
let washIn;
let dust;
let papers;

export function mount(context) {
  ctx = context;
  const rng = mulberry32(4242);
  dust = Array.from({ length: 84 }, () => ({
    ang: rng() * Math.PI * 2,
    v: 200 + rng() * 980,
    r0: 26 + rng() * 200,
    t0: 0.04 + rng() * 2.1,
    w: 2.4 + rng() * 5.2,
    len: 28 + rng() * 64,
    a: 0.16 + rng() * 0.4,
    amber: rng() < 0.62,
  }));
  papers = Array.from({ length: 7 }, () => ({
    ang: rng() * Math.PI * 2,
    v: 260 + rng() * 680,
    r0: 30 + rng() * 140,
    t0: 0.55 + rng() * 1.7,
    s: 0.28 + rng() * 0.5,
    spin: (rng() < 0.5 ? -1 : 1) * (2.6 + rng() * 4),
  }));
  pinGlow = makeGlow({ w: 520, h: 520, step: 10, hotR: 0.11, seed: 21 });
  wash = makeGlow({ w: 2400, h: 1800, step: 18, angle: 0.22, hotR: 0, power: 1.12, seed: 31 });
  washIn = makeGlow({ w: 1000, h: 1000, step: 15, angle: 0.24, hotR: 0, power: 1.35, seed: 41 });
  base = stillAt(ctx, 1.22, drawBase);
}

function archPath(g, halfW = MOUTH.halfW, grow = 0) {
  const x = MOUTH.x;
  const top = MOUTH.top - grow;
  const bottom = MOUTH.bottom + grow * 0.3;
  const hw = halfW + grow;
  const r = hw;
  g.beginPath();
  g.moveTo(x - hw, bottom);
  g.lineTo(x - hw, top + r);
  g.arc(x, top + r, r, Math.PI, 0);
  g.lineTo(x + hw, bottom);
  g.closePath();
}

function drawBase(g) {
  g.fillStyle = C.ink;
  g.fillRect(0, 0, W, H);

  // --- 洞口周围的瓷砖墙：一块一块地画，颜色有一档差别 ---
  const rng = mulberry32(77);
  const TW = 132;
  const TH = 128;
  const tilesW = Math.ceil(W / TW);
  const tilesH = Math.ceil(MOUTH.bottom / TH);
  for (let r = 0; r < tilesH; r++) {
    for (let c = 0; c < tilesW; c++) {
      const v = rng();
      g.fillStyle = v < 0.18 ? '#251e1a' : v < 0.32 ? '#2f2620' : C.struct;
      g.fillRect(c * TW, r * TH, TW, TH);
    }
  }
  // 缝
  g.strokeStyle = C.grout;
  g.lineWidth = 1.8;
  for (let x = 0; x <= W; x += TW) {
    g.beginPath();
    g.moveTo(x, 0);
    g.lineTo(x, MOUTH.bottom);
    g.stroke();
  }
  for (let y = 0; y <= MOUTH.bottom; y += TH) {
    g.beginPath();
    g.moveTo(0, y);
    g.lineTo(W, y);
    g.stroke();
  }
  // 腰线：一条哑红（比黄线暗，不抢）
  g.fillStyle = '#7a2b1f';
  g.fillRect(0, 706, W, 30);
  g.fillStyle = C.boneDim;
  g.fillRect(0, 704, W, 2);

  // 檐口
  g.fillStyle = C.boneDim;
  g.fillRect(0, 148, W, 3);
  g.fillStyle = C.ink;
  g.fillRect(0, 0, W, 148);

  // 墙上的电缆管：一根横的，几段卡子
  g.fillStyle = '#3b2f26';
  g.fillRect(0, 214, W, 7);
  g.fillStyle = C.boneDim;
  for (let x = 60; x < W; x += 260) g.fillRect(x, 210, 10, 15);

  // 进站信号灯：一根杆 + 一个黄灯（提示"车要来了"）
  g.fillStyle = C.ink;
  g.fillRect(232, 400, 14, 560);
  fillPoly(g, [[196, 380], [282, 380], [296, 470], [182, 470]], C.deep, { amp: 2, seed: 12 });
  g.fillStyle = C.ink;
  g.fillRect(210, 392, 58, 22);
  g.beginPath();
  g.arc(239, 440, 20, 0, Math.PI * 2);
  g.fillStyle = C.ink;
  g.fill();

  // --- 洞口的混凝土圈：外圈一道骨白，压出一条发亮的边 ---
  archPath(g, MOUTH.halfW + 30, 26);
  g.fillStyle = C.flat;
  g.fill();
  g.save();
  archPath(g, MOUTH.halfW + 30, 26);
  g.strokeStyle = '#4a3a2d';
  g.lineWidth = 3;
  g.stroke();
  g.restore();
  archPath(g);
  g.fillStyle = C.deep;
  g.fill();

  // 洞里的两条钢轨
  g.save();
  g.globalAlpha = 0.55;
  taper(g, 896, MOUTH.bottom + 2, 918, 700, 6, 1.6, C.amberDim);
  taper(g, 944, MOUTH.bottom + 2, 922, 700, 6, 1.6, C.amberDim);
  g.restore();

  // --- 站台边：轨行区、红色鼻线、黄线（都压暗，它们是底不是主角） ---
  g.fillStyle = '#0b0908';
  g.fillRect(0, PIT_TOP, W, EDGE_TOP - PIT_TOP);
  g.fillStyle = '#6b2a1f';
  g.fillRect(0, EDGE_TOP - 12, W, 14);
  g.fillStyle = C.bone;
  g.fillRect(0, EDGE_TOP - 14, W, 3);
  g.fillStyle = C.structLite;
  g.fillRect(0, EDGE_TOP + 1, W, H - EDGE_TOP);
  g.save();
  g.globalAlpha = 0.6;
  g.fillStyle = C.amber;
  g.fillRect(0, 1042, W, 10);
  g.fillStyle = C.boneDim;
  g.fillRect(0, 1052, W, 2);
  g.restore();
  g.fillStyle = C.ink;
  g.fillRect(0, 1068, W, 3);
}

export function render(t) {
  const g = ctx.canvas.getContext('2d');
  const z = 1 + 0.1 * easeInOut(t / 3.3);
  plate(g, base, { z, cx: MOUTH.x, cy: 640 });

  const L = smooth((t - 0.32) / 2.05); // 灯涨
  const N = smooth((t - 2.28) / 0.95); // 车头长出来

  // --- 墙本来就是被洞里的光洗过的；灯涨，网点就铺开 ---
  g.save();
  g.globalAlpha = 0.16 + 0.4 * L;
  blit(g, wash, MOUTH.x, 780, 0.3 + 0.26 * L, 1);
  g.restore();
  {
    // 洞口内壁被照亮：裁在洞里，用一张小的网点，点的大小才看得见变化
    g.save();
    archPath(g);
    g.clip();
    blit(g, washIn, MOUTH.x, 790, 0.42 + 0.3 * L, 0.6 * L);
    g.restore();
  }

  // --- 洞口边被灯照亮的一圈（必须在车头之前，不然会压在车脸上） ---
  if (L > 0) {
    g.save();
    g.globalAlpha = 0.6 * L;
    archPath(g);
    g.strokeStyle = C.amberDim;
    g.lineWidth = 7;
    g.stroke();
    g.restore();
  }

  // --- 车头：一块黑，只留一道骨白前缘 ---
  if (N > 0) {
    const hw = 360 * N + 60;
    const h = 660 * N + 130;
    const top = MOUTH.bottom - h;
    const r = 46;
    g.beginPath();
    g.moveTo(MOUTH.x - hw, MOUTH.bottom);
    g.lineTo(MOUTH.x - hw, top + r);
    g.quadraticCurveTo(MOUTH.x - hw, top, MOUTH.x - hw + r, top);
    g.lineTo(MOUTH.x + hw - r, top);
    g.quadraticCurveTo(MOUTH.x + hw, top, MOUTH.x + hw, top + r);
    g.lineTo(MOUTH.x + hw, MOUTH.bottom);
    g.closePath();
    g.fillStyle = C.deep;
    g.fill();
    // 前脸：风挡一块更暗的方，底下一条黄的裙灯
    g.save();
    g.globalAlpha = 0.75;
    g.fillStyle = '#1d1815';
    g.fillRect(MOUTH.x - hw * 0.78, top + 56, hw * 1.56, h * 0.4);
    g.restore();
    g.fillStyle = C.amber;
    g.fillRect(MOUTH.x - hw + 18, MOUTH.bottom - 26, hw * 2 - 36, 9);
    // 前脸下沿一条红的裙线、中间一块车钩的黑
    g.fillStyle = C.red;
    g.fillRect(MOUTH.x - hw + 22, MOUTH.bottom - 52, hw * 2 - 44, 16);
    g.fillStyle = C.ink;
    g.fillRect(MOUTH.x - 46, MOUTH.bottom - 120, 92, 120);
    // 骨白前缘：车头压过来时唯一能看见的边
    g.strokeStyle = C.boneDim;
    g.lineWidth = 3;
    g.beginPath();
    g.moveTo(MOUTH.x - hw, MOUTH.bottom);
    g.lineTo(MOUTH.x - hw, top + r);
    g.quadraticCurveTo(MOUTH.x - hw, top, MOUTH.x - hw + r, top);
    g.lineTo(MOUTH.x + hw - r, top);
    g.quadraticCurveTo(MOUTH.x + hw, top, MOUTH.x + hw, top + r);
    g.lineTo(MOUTH.x + hw, MOUTH.bottom);
    g.stroke();
  }

  // --- 两盏车头灯 ---
  const spread = 32 + 168 * L;
  const ly = 742;
  const glowScale = 0.1 + 0.52 * L;
  for (const sx of [-1, 1]) {
    blit(g, pinGlow, MOUTH.x + sx * spread, ly, glowScale * (1 + 0.12 * N), 0.9);
  }
  // 灯下的反光：钢轨上两点黄
  g.save();
  g.globalAlpha = 0.5 + 0.4 * L;
  taper(g, MOUTH.x - spread, ly + 40, MOUTH.x - 18, PIT_TOP - 4, 3, 1.2, C.amber);
  taper(g, MOUTH.x + spread, ly + 40, MOUTH.x + 18, PIT_TOP - 4, 3, 1.2, C.amber);
  g.restore();

  // --- 风把纸屑从洞里推出来 ---
  for (const p of papers) {
    const age = t - p.t0;
    if (age <= 0) continue;
    const r = p.r0 + p.v * age * 1.25;
    const x = MOUTH.x + Math.cos(p.ang) * r * 1.35;
    const y = 742 + Math.sin(p.ang) * r * 0.95;
    if (x < -180 || x > W + 180 || y < -160 || y > H + 160) continue;
    const s = p.s * (1 + r / 900);
    if (s > 3.4) continue;
    scrap(g, x, y, s, p.spin * age, Math.cos(age * 4.2), { lines: false });
  }

  // --- 尘土：径向冲出来，越近越大 ---
  const windAmt = smooth((t - 0.02) / 0.8);
  for (const d of dust) {
    const age = t - d.t0;
    if (age <= 0) continue;
    const r = d.r0 + d.v * age * 1.2;
    const r2 = d.r0 + d.v * Math.max(0, age - 0.06) * 1.2;
    const ux = Math.cos(d.ang) * 1.3;
    const uy = Math.sin(d.ang) * 0.9;
    const x = MOUTH.x + ux * r;
    const y = 742 + uy * r;
    const x2 = MOUTH.x + ux * r2 * 0.93;
    const y2 = 742 + uy * r2 * 0.93;
    if (x < -160 || x > W + 160 || y < -160 || y > H + 160) continue;
    const a = d.a * clamp01(age / 0.25) * windAmt;
    const w = d.w * (0.7 + r / 1100);
    const mx = (x + x2) / 2 + Math.cos(d.ang + 1.57) * w * 0.55;
    const my = (y + y2) / 2 + Math.sin(d.ang + 1.57) * w * 0.55;
    const col = d.amber ? C.amber : C.bone;
    taper(g, x2, y2, mx, my, w * 0.12, w * 0.7, col, a * 0.75);
    taper(g, mx, my, x, y, w * 0.7, w, col, a);
  }

  // --- 进站信号：黄灯亮着，车来之前一直亮 ---
  const sig = 0.5 + 0.5 * smooth((t - 0.6) / 1.2);
  blit(g, pinGlow, 239, 440, 0.08 + 0.02 * sig, 0.85);
  g.beginPath();
  g.arc(239, 440, 13, 0, Math.PI * 2);
  g.fillStyle = C.amber;
  g.fill();
  g.beginPath();
  g.arc(239, 440, 4.5, 0, Math.PI * 2);
  g.fillStyle = C.bone;
  g.fill();

  paperEdge(g);
}
